// url=https://www.figma.com/design/yhUDpqfUinkGXN6zgpJVUQ/UI-Kit?node-id=7144-35008
// source=https://gip-inclusion.github.io/itou-theme/doc/?path=/docs/components-tooltips--docs (icon trigger)
// component=Tooltip
const figma = require('figma')
const instance = figma.selectedInstance

const text = instance.getString('Text')
const placement = instance.getEnum('Direction', { Top: 'top', Right: 'right', Bottom: 'bottom', Left: 'left' })

// The bubble is generated by Bootstrap: the code lives on the trigger.
export default {
  example: figma.html`<i class="ri-information-line ri-xl text-info" aria-label="Afficher une information complémentaire" data-bs-toggle="tooltip" data-bs-placement="${placement}" data-bs-title="${text}" role="button" tabindex="0"></i>`,
  id: 'tooltip',
  metadata: { nestable: true },
}
